import{_ as t,o,c as a,a2 as r}from"./chunks/framework.du4mJiD7.js";const m=JSON.parse('{"title":"Workouts have a format, not a type","description":"","frontmatter":{"status":"accepted","date":"2026-10-26T00:00:00.000Z"},"headers":[],"relativePath":"docs/adr/0013-workouts-have-a-format-not-a-type.md","filePath":"docs/adr/0013-workouts-have-a-format-not-a-type.md"}'),s={name:"docs/adr/0013-workouts-have-a-format-not-a-type.md"};function n(i,e,h,d,p,l){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="workouts-have-a-format-not-a-type" tabindex="-1">Workouts have a format, not a type <a class="header-anchor" href="#workouts-have-a-format-not-a-type" aria-label="Permalink to &quot;Workouts have a format, not a type&quot;">​</a></h1><p>Supersedes <a href="./0004-workout-types-are-modules-over-one-engine">ADR 0004</a>.</p><p>A workout no longer has a workout type (strength, conditioning, rehab, mobility, treadmill). It has a <strong>format</strong>, circuit or sets, chosen when it is created, and is made of <strong>parts</strong>: an optional warm-up, one or more work parts and an optional cool down.</p><p>The five type modules had converged on one rule: a time or a hold runs a timer, and reps, a distance or an open target wait for a tap. The type only decided which exercises the builder offered and a label, while people kept mixing a run warm-up with squats or a walk cool down with stretches. What they actually choose is how the workout is built: rounds through several exercises, each done once per round, or one exercise at a time with all its sets. That is the format. Warming up and cooling down are sections of the workout rather than tags on single steps, so they became parts.</p><p>The engine reads the completion rule from the target, compiles the parts in order, and tells each phase which part it belongs to. <code>WorkoutTypeModule</code>, its registry and the strength, conditioning, rehab and mobility modules are gone; <code>types/treadmill</code> stays for the treadmill&#39;s own logic (recording, summary, step estimate). What the type used to drive elsewhere comes from the format or from the exercises: the Live picker offers workouts made of walks and runs, and the FIT sport follows the format and the exercises.</p><p>Saved workouts were not converted when this landed: the app was only on its author&#39;s phones, so the migration removes them and their planned days, and past sessions stay in the history without a format.</p>',6)])])}const u=t(s,[["render",n]]);export{m as __pageData,u as default};
